mapper.select:
select d.id, d.status, d.assets_id, d.goods_code, d.goods_name, d.bar_code, d.package_specification, d.package_specification_num, d.package_quantity, d.order_quantity, d.surplus_quantity, ROUND(d.surplus_quantity / d.package_specification_num,2) as surplus_package_quantity, d.presale_activity_id, d.presale_activity_no, d.begin_order_date, d.end_order_date from ord_dis_presale_assets_detail d inner join ord_dis_presale_assets a on a.id = d.assets_id where d.assets_id = #{assetsId}
and d.presale_activity_no = #{presaleActivityNo}
and d.bar_code = #{barCode}
and d.goods_code = #{goodsCode}
and d.status = #{status}
and d.begin_order_date >= #{beginOrderTime} and d.end_order_date <= #{endOrderTime}
and a.biz_org_code = #{bizOrgCode}
and d.surplus_quantity != 0 order by d.end_order_date desc,d.presale_activity_no
